import { readFileSync } from 'node:fs'
const SRC = readFileSync('lib/client.js', 'utf8')
const koStart = SRC.indexOf('      ko: {')
const enStart = SRC.indexOf('      en: {')
const end = SRC.indexOf('// ===== I18N END')
const keysIn = (block) => new Set([...block.matchAll(/^\s+([a-zA-Z][a-zA-Z0-9]*):\s+'/gm)].map((m) => m[1]))
const ko = keysIn(SRC.slice(koStart, enStart))
const en = keysIn(SRC.slice(enStart, end))
const called = new Set([...SRC.matchAll(/\bt\('([a-zA-Z]+)'/g)].map((m) => m[1]))
called.delete('style')
console.log('called keys :', [...called].sort().join(', '))
console.log('missing ko  :', JSON.stringify([...called].filter((k) => !ko.has(k))))
console.log('missing en  :', JSON.stringify([...called].filter((k) => !en.has(k))))
console.log('dictionary ko keys:', [...ko].sort().join(', '))
